message.content:
{
  "events": [
    {
      "key": "sao_safezone_clue",
      "choices": [
        {
          "index": 1,
          "actionText": "리즈벳에게 보낸 장비 질문에 대한 제작 공정을 정밀 조사하며 가공 비용 160골드를 냈다.",
          "reactionText": "리즈벳은 조작 여부를 확인하는 기술을 빌려주며 아직 해결되지 않은 증언의 모순을 언급했다."
        },
        {
          "index": 2,
          "actionText": "아스나와 함께 현장을 돌며 목격자들을 대조하여 엇갈리는 증언 사이의 모순을 찾아냈다.",
          "reactionText": "아스나는 현장의 위화감을 짚어내며 여전히 장비의 제작 기록과 대조가 필요함을 알렸다."
        },
        {
          "index": 3,
          "actionText": "180골드로 기록 도구를 마련하고 키리토와 확인된 흔적만 나누기로 했다.",
          "reactionText": "키리토는 메모를 확인하며 아직 정리되지 않은 장비의 면과 증언의 순서를 짚었다."
        }
      ]
    },
    {
      "key": "sao_counter_labels",
      "choices": [
        {
          "index": 1,
          "actionText": "기록용품 값 180골드를 내고 에길과 겹친 값표를 맞췄다.",
          "reactionText": "에길은 아직 확인하지 않은 상자부터 가리키며 키리토가 가져올 물건을 물었다."
        },
        {
          "index": 2,
          "actionText": "키리토와 더 강한 적이 오가는 운반 길목을 맡았다.",
          "reactionText": "에길은 그 길목으로 나갈 상자만 따로 나누며 운반을 준비했다."
        },
        {
          "index": 3,
          "actionText": "110골드로 보급을 마련하고 에길과 물품의 무게를 다시 확인했다.",
          "reactionText": "에길은 무게를 재확인하며 겹친 값표를 다시 정리했다."
        }
      ]
    },
    {
      "key": "sao_guild_roll",
      "choices": [
        {
          "index": 1,
          "actionText": "준비 도구 값 200골드를 내고 클라인과 앞뒤 역할을 나누었다.",
          "reactionText": "키리토는 뒤에 남길 몫이 빠지지 않았는지 다시 물으며 준비를 점검했다."
        },
        {
          "index": 2,
          "actionText": "클라인과 더 많은 적이 오가는 옆길을 맡았다.",
          "reactionText": "클라인은 앞쪽뿐 아니라 돌아올 쪽에도 표시를 남기며 길을 안내했다."
        },
        {
          "index": 3,
          "actionText": "160골드로 운반 도구를 마련하고 클라인과 맡을 길목을 줄였다.",
          "reactionText": "클라인은 줄어든 길목을 확인하며 다음 이동을 준비했다."
        }
      ]
    },
    {
      "key": "sao_middle_lantern",
      "choices": [
        {
          "index": 1,
          "actionText": "준비물 값 220골드를 내고 사치와 더 약한 담당 구역을 정했다.",
          "reactionText": "사치는 대답을 서두르지 않고 돌아올 자리의 표시를 한 번 더 보았다."
        },
        {
          "index": 2,
          "actionText": "키리토와 더 강한 적이 오가는 바깥 길목을 맡았다.",
          "reactionText": "키리토는 사치가 아직 나누지 않은 준비물을 옆에 남겨두었다."
        },
        {
          "index": 3,
          "actionText": "160골드로 표시 용품을 마련하고 키리토와 등불을 볼 길목을 줄였다.",
          "reactionText": "키리토는 줄어든 길목을 확인하며 사치와 구역을 재확인했다."
        }
      ]
    },
    {
      "key": "sao_lakeside_wait",
      "choices": [
        {
          "index": 1,
          "actionText": "미끼값 150골드를 내고 작은 입질의 때를 맞췄다.",
          "reactionText": "니시다는 호수의 주인보다 방금 잠잠해진 찌를 먼저 보고 있었다."
        },
        {
          "index": 2,
          "actionText": "210골드로 기다릴 자리를 마련하고 니시다 옆에서 찌가 변할 때를 보았다.",
          "reactionText": "니시다는 찌의 움직임을 살피며 입질을 기다렸다."
        },
        {
          "index": 3,
          "actionText": "더 많은 개인 사냥을 맡으며 아스나와 몸 상태를 유지할 준비를 했다.",
          "reactionText": "아스나는 기다릴 자리에 앉고 네가 가져갈 보급을 옆에 남겼다."
        }
      ]
    }
  ]
}
